function [m] = bdot(b1, b2, dt, bn, k, m_max)
%BDOT  B-dot on two successive field directions dt apart, gain k over the field strength bn.
%   b1: real[1][3] (passed a plain number)
%   b2: real[1][3] (passed a plain number)
%   dt: real[1] (passed a plain number)
