    m = zeros(3, 1);
    h__61 = sqrt(b1(1)*b1(1) + b1(2)*b1(2) + b1(3)*b1(3));
    if 1e-30 > h__61, h__61 = 1e-30; end
    u1 = (b1 / h__61);
    h__62 = sqrt(b2(1)*b2(1) + b2(2)*b2(2) + b2(3)*b2(3));
    if 1e-30 > h__62, h__62 = 1e-30; end
    u2 = (b2 / h__62);
    r = zeros(3, 1);
